const $ = selector => document.querySelector(selector);
const escapeHtml = (value = '') => String(value).replace(/[&<>'"]/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[character]));
let currentUser = null;
const api = async (url, options = {}) => { const response = await fetch(url, { ...options, headers: { 'content-type': 'application/json', ...(options.headers || {}) } }); const body = await response.json().catch(() => ({})); if (!response.ok) throw Object.assign(new Error(body.error || 'Une erreur est survenue.'), { status: response.status }); return body; };
const splitOrderField = value => String(value || '').split('\n').map(line => line.replace(/^\s*\d+\.\s*/, '').trim()).filter(Boolean);
function articlesMarkup(order) { const products = splitOrderField(order.product), sizes = splitOrderField(order.size), budgets = splitOrderField(order.budget), details = splitOrderField(order.details); return `<div class="orderArticles">${products.map((product, index) => `<div class="orderArticle"><strong>Article ${index + 1}</strong><b>${escapeHtml(product)}</b><p><span>Taille</span>${escapeHtml(sizes[index] || 'Sans taille')} <i>·</i> <span>Budget</span>${escapeHtml(budgets[index] || 'Non indiqué')}</p>${details[index] && details[index] !== 'Aucun détail complémentaire' ? `<p class="articleDetails">${escapeHtml(details[index])}</p>` : ''}</div>`).join('')}</div>`; }
function pageFromUrl() { const page = new URLSearchParams(location.search).get('page'); return ['demande', 'suivi', 'avis', 'administration'].includes(page) ? page : 'accueil'; }
function closeMenu() { document.body.classList.remove('menuOpen'); $('#menuToggle').setAttribute('aria-expanded', 'false'); $('#sideMenu').setAttribute('aria-hidden', 'true'); $('#menuOverlay').hidden = true; }
function openMenu() { document.body.classList.add('menuOpen'); $('#menuToggle').setAttribute('aria-expanded', 'true'); $('#sideMenu').setAttribute('aria-hidden', 'false'); $('#menuOverlay').hidden = false; }
function showPage(pageId, updateUrl = true) {
  const currentPage = ['demande', 'suivi', 'avis', 'administration'].includes(pageId)
    ? pageId
    : 'accueil';

  document.querySelectorAll('.page').forEach(section => {
    const active = section.id === currentPage;

    section.classList.toggle('pageActive', active);
    section.hidden = !active;
    section.style.display = active
      ? (currentPage === 'demande' ? 'grid' : 'block')
      : 'none';
  });

  document.querySelectorAll('[data-nav-page]').forEach(link => {
    link.classList.toggle('active', link.dataset.navPage === currentPage);
  });

  if (updateUrl) {
    history.replaceState(
      null,
      '',
      currentPage === 'accueil' ? '/' : `/?page=${currentPage}`,
    );
  }

  closeMenu();
  window.scrollTo({ top: 0, behavior: 'auto' });
}


const ORDER_TIMELINE = [
  ['Demande', 'Ta demande a bien été reçue.'],
  ['Recherche', 'Nous recherchons le meilleur produit pour ta demande.'],
  ['Proposition', 'Une proposition est prête à être validée.'],
  ['Commandée', 'Le produit a été commandé pour toi.'],
  ['Expédiée', 'Ton colis est en route.'],
  ['Livrée', 'Commande reçue et terminée.'],
];
const STATUS_STAGE = { new: 1, product_to_pay: 2, product_paid: 3, shipping_to_pay: 3, shipped: 4, receipt_confirmation: 5, closed: 6, archived: 6 };
function timelineMarkup(order) {
  const stage = STATUS_STAGE[order.status] ?? 0;
  return `<ol class="orderTimeline">${ORDER_TIMELINE.map(([label, detail], index) => {
    const done = index < stage;
    const active = stage < ORDER_TIMELINE.length && index === stage;
    return `<li class="timelineStep ${done ? 'done' : ''} ${active ? 'active' : ''}"><span class="timelineDot" aria-hidden="true">${done ? '✓' : String(index + 1).padStart(2, '0')}</span><div><b>${label}</b><p>${detail}</p></div></li>`;
  }).join('')}</ol>`;
}

function orderCard(order) { const date = new Intl.DateTimeFormat('fr-FR', { dateStyle: 'long', timeStyle: 'short' }).format(new Date(order.created_at)); const review = order.status === 'receipt_confirmation' ? `<button class="reviewButton premiumAction" data-review="${order.id}">Confirmer la réception & laisser un avis</button>` : ''; return `<article class="order customerOrder"><div class="orderHeader"><div><small>COMMANDE</small><h3>#CSP-${order.id}</h3><p class="orderDate">Demandée le ${date}</p></div><span class="statusPill">${escapeHtml(order.status_label)}</span></div>${articlesMarkup(order)}<div class="timelinePanel"><p class="timelineKicker">SUIVI DE COMMANDE</p>${timelineMarkup(order)}</div><div class="orderActions"><button class="chatToggle premiumAction" data-chat="${order.id}">Discuter avec C SHOP.FR</button>${review}</div><div class="chat hidden" id="chat-${order.id}"></div></article>`; }
async function refreshUser() { const data = await api('/api/auth/me', { headers: {} }); currentUser = data.user; $('#loginButton').textContent = currentUser ? `${currentUser.name} · Déconnexion` : 'Se connecter avec Google'; const email = $('#requestForm input[name="email"]'); if (email) { if (currentUser) { email.value = currentUser.email; email.readOnly = true; } else email.readOnly = false; } $('#adminNavLink').classList.toggle('hidden', !currentUser?.admin); return currentUser; }
function connect(destination = 'accueil') { window.location.assign(`/api/auth/google?next=${encodeURIComponent(destination)}`); }
async function showOrders() { if (!currentUser) return connect('suivi'); try { const { orders } = await api('/api/orders', { headers: {} }); $('#accountLine').textContent = `Connecté avec ${currentUser.email}`; $('#ordersContent').innerHTML = orders.length ? orders.map(orderCard).join('') : '<p>Tu n’as encore envoyé aucune demande. Utilise « Faire une demande » pour commencer.</p>'; } catch (error) { $('#ordersContent').innerHTML = `<p>${escapeHtml(error.message)}</p>`; } showPage('suivi'); }
function reviewCard(review) { const stars = '★'.repeat(review.rating) + '☆'.repeat(5 - review.rating); const date = new Intl.DateTimeFormat('fr-FR', { year: 'numeric', month: 'long' }).format(new Date(review.reviewed_at)); return `<article class="reviewCard"><div class="reviewTop"><span class="reviewAvatar" aria-hidden="true">C</span><div><b>Client C SHOP.FR</b><small>Avis vérifié · ${date}</small></div><span class="reviewDots" aria-hidden="true">⋮</span></div><p class="reviewStars" aria-label="${review.rating} étoiles sur 5">${stars}</p><p class="reviewText">${escapeHtml(review.comment)}</p></article>`; }

function homeReviewCard(review) { const stars = '★'.repeat(review.rating) + '☆'.repeat(5 - review.rating); return `<article class="homeReviewCard"><p class="homeReviewStars" aria-label="${review.rating} étoiles sur 5">${stars}</p><p class="homeReviewText">“${escapeHtml(review.comment)}”</p><div class="homeReviewMeta"><span class="reviewAvatar" aria-hidden="true">C</span><div><b>Client C SHOP.FR</b><small>Avis vérifié</small></div></div></article>`; }
async function loadHomeReviews() { const target = $('#homeReviewsContent'); if (!target) return; try { const { reviews } = await api('/api/reviews', { headers: {} }); target.innerHTML = reviews.length ? reviews.slice(0, 3).map(homeReviewCard).join('') : '<p class="homeReviewsEmpty">Les premiers avis vérifiés apparaîtront ici après les commandes.</p>'; } catch { target.innerHTML = '<p class="homeReviewsEmpty">Les avis seront disponibles ici très bientôt.</p>'; } }

async function showReviews() { $('#reviewsContent').innerHTML = '<p class="reviewsLoading">Chargement des avis…</p>'; showPage('avis'); try { const { reviews } = await api('/api/reviews', { headers: {} }); $('#reviewsContent').innerHTML = reviews.length ? reviews.map(reviewCard).join('') : '<p class="reviewsEmpty">Les premiers avis apparaîtront ici après les commandes.</p>'; } catch (error) { $('#reviewsContent').innerHTML = '<p class="reviewsEmpty">Impossible de charger les avis pour le moment.</p>'; } }
function openRequest(product = '') { showPage('demande'); const article = document.querySelector('[data-article]'); if (article && product) article.querySelector('[name="product"]').value = product; setTimeout(() => (article?.querySelector('[name="product"]') || $('#requestForm input[name="product"]'))?.focus(), 400); }
function adminCard(order) { const states = [['new','Demande reçue'],['product_to_pay','Produit à payer'],['product_paid','Produit payé'],['shipped','Colis expédié'],['receipt_confirmation','Réception à confirmer'],['closed','Terminée']]; const selectedStatus = order.status === 'shipping_to_pay' ? 'product_paid' : order.status; const close = `<button class="closeOrderButton" data-close-order="${order.id}">Fermer la commande</button>`; return `<article class="order adminOrder"><div class="adminSummary"><p class="status">${escapeHtml(order.status_label)}</p><b>#${order.id}</b><p><strong>${escapeHtml(order.first_name)} ${escapeHtml(order.last_name)}</strong> · ${escapeHtml(order.customer_email)} · ${escapeHtml(order.phone)}</p><p>${escapeHtml(order.city)}</p>${articlesMarkup(order)}</div><div class="adminControls"><label>STATUT <select data-status="${order.id}">${states.map(([value, text]) => `<option value="${value}" ${value === selectedStatus ? 'selected' : ''}>${text}</option>`).join('')}</select></label><button class="updateButton" data-update="${order.id}">Mettre à jour</button>${close}</div><div class="adminChat"><button class="chatToggle" data-chat="${order.id}">Discuter avec le client</button><div class="chat hidden" id="chat-${order.id}"></div></div></article>`; }
async function showAdmin() { if (!currentUser) return connect('administration'); try { const { orders } = await api('/api/admin/orders', { headers: {} }); $('#adminContent').innerHTML = orders.length ? orders.map(adminCard).join('') : '<p>Aucune demande pour le moment.</p>'; } catch (error) { $('#adminContent').innerHTML = `<p>${escapeHtml(error.message)}</p>`; } showPage('administration'); }
document.querySelectorAll('[data-open-request]').forEach(button => button.onclick = () => openRequest()); document.querySelectorAll('[data-open-orders]').forEach(button => button.onclick = showOrders); document.querySelectorAll('[data-open-reviews]').forEach(button => button.onclick = showReviews); document.querySelectorAll('.productCard[data-product]').forEach(card => { const openProduct = () => openRequest(card.dataset.product); card.onclick = openProduct; card.onkeydown = event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); openProduct(); } }; });
$('#menuToggle').onclick = () => document.body.classList.contains('menuOpen') ? closeMenu() : openMenu();
$('#menuClose').onclick = closeMenu;
$('#menuOverlay').onclick = closeMenu;
document.querySelectorAll('.menuNav [data-nav-page]').forEach(button => button.onclick = () => { const page = button.dataset.navPage; if (page === 'suivi') return showOrders(); if (page === 'avis') return showReviews(); if (page === 'administration') return showAdmin(); showPage(page); });
document.querySelectorAll('.menuNav [data-nav-section]').forEach(button => button.onclick = () => { const targetId = button.dataset.navSection; showPage('accueil'); requestAnimationFrame(() => { const target = document.getElementById(targetId); if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' }); }); });

document.querySelectorAll('[data-footer-page]').forEach(button => button.onclick = () => { const page = button.dataset.footerPage; if (page === 'suivi') return showOrders(); if (page === 'avis') return showReviews(); showPage(page); });
document.querySelectorAll('[data-footer-section]').forEach(button => button.onclick = () => { const targetId = button.dataset.footerSection; showPage('accueil'); requestAnimationFrame(() => document.getElementById(targetId)?.scrollIntoView({ behavior: 'smooth', block: 'start' })); });

const revealSections = document.querySelectorAll('.revealSection');
if ('IntersectionObserver' in window) { const revealObserver = new IntersectionObserver(entries => { entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('isVisible'); revealObserver.unobserve(entry.target); } }); }, { threshold: 0.12, rootMargin: '0px 0px -45px' }); revealSections.forEach(section => revealObserver.observe(section)); } else revealSections.forEach(section => section.classList.add('isVisible'));
$('#loginButton').onclick = async () => { if (!currentUser) return connect(); await api('/api/auth/logout', { method: 'POST' }); currentUser = null; $('#loginButton').textContent = 'Se connecter avec Google'; $('#adminNavLink').classList.add('hidden'); showPage('accueil'); };
function refreshArticleLabels() { document.querySelectorAll('[data-article]').forEach((article, index) => { article.querySelector('legend').textContent = `ARTICLE ${index + 1}`; const remove = article.querySelector('.removeArticle'); if (remove) remove.hidden = index === 0; }); }
function makeArticle() { const article = document.querySelector('[data-article]').cloneNode(true); article.querySelectorAll('input, textarea').forEach(field => field.value = ''); const file = article.querySelector('input[type="file"]'); if (file) file.value = ''; const remove = document.createElement('button'); remove.type = 'button'; remove.className = 'removeArticle'; remove.textContent = 'Retirer cet article'; article.append(remove); $('#articles').append(article); refreshArticleLabels(); article.querySelector('[name="product"]').focus(); }
const addArticleButton = $('#addArticle'); if (addArticleButton) addArticleButton.onclick = makeArticle;
document.addEventListener('click', event => { const remove = event.target.closest('.removeArticle'); if (remove) { remove.closest('[data-article]').remove(); refreshArticleLabels(); return; } const chat = event.target.closest('[data-chat]'); if (chat) return openChat(chat.dataset.chat); const update = event.target.closest('[data-update]'); if (update) return updateOrder(update); const closeOrder = event.target.closest('[data-close-order]'); if (closeOrder) return closeOrderAdmin(closeOrder); const review = event.target.closest('[data-review]'); if (review) return addReview(review); });
$('#requestForm').onsubmit = async event => { event.preventDefault(); const form = event.currentTarget; if (!form.reportValidity()) return; const message = $('#formMessage'); const submit = form.querySelector('.send'); if (!currentUser) { message.className = 'message isError'; message.textContent = 'Connecte-toi avec Google avant d’envoyer ta demande.'; return connect(); } const customer = Object.fromEntries(new FormData(form)); const articles = [...form.querySelectorAll('[data-article]')].map(article => ({ product: article.querySelector('[name="product"]').value.trim(), size: article.querySelector('[name="size"]').value.trim(), budget: article.querySelector('[name="budget"]').value.trim(), details: article.querySelector('[name="remarks"]')?.value.trim() || '' })); submit.disabled = true; submit.classList.add('isLoading'); submit.querySelector('.sendLabel').textContent = 'Envoi en cours'; message.className = 'message sendingMessage'; message.innerHTML = '<span class="inlineLoader" aria-hidden="true"></span><span>Envoi de ta demande…</span>'; try { const result = await api('/api/orders', { method: 'POST', body: JSON.stringify({ ...customer, articles }) }); submit.classList.remove('isLoading'); submit.classList.add('isSuccess'); submit.querySelector('.sendLabel').textContent = 'Demande envoyée'; submit.querySelector('.sendArrow').textContent = '✓'; message.className = 'message successMessage'; message.innerHTML = `<span class="successCheck" aria-hidden="true">✓</span><span><b>Demande envoyée avec succès !</b><small>Commande n°${result.id} · redirection vers le suivi…</small></span>`; form.reset(); [...form.querySelectorAll('[data-article]')].slice(1).forEach(article => article.remove()); refreshArticleLabels(); setTimeout(showOrders, 1100); } catch (error) { submit.disabled = false; submit.classList.remove('isLoading'); submit.querySelector('.sendLabel').textContent = 'Envoyer la demande'; submit.querySelector('.sendArrow').textContent = '↗'; message.className = 'message isError'; message.textContent = error.message; } };
function chatMarkup(messages) { return `<div class="chatMessages">${messages.length ? messages.map(message => `<div class="chatMessage ${message.mine ? 'mine' : ''}"><span class="chatMeta">${message.author_role === 'admin' ? 'C SHOP.FR' : 'Client'} · ${new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(message.created_at))}</span>${message.message ? `<span class="chatText">${escapeHtml(message.message)}</span>` : ''}${(message.files||[]).map(file => `<a class="chatFile" href="/api/orders/${message.order_id||''}/files/${file.id}" data-file-id="${file.id}" download>📎 ${escapeHtml(file.file_name)} <small>${Math.ceil(file.size_bytes/1024)} Ko</small></a>`).join('')}</div>`).join('') : '<p class="legal">Aucun message pour le moment. Écris le premier.</p>'}</div><form class="chatForm" data-chat-form><input name="message" maxlength="1200" placeholder="Écrire un message…" aria-label="Message"><label class="chatFileButton">📎 Fichier<input name="files" type="file" multiple></label><button type="submit">Envoyer</button><small class="chatHelp">4 fichiers maximum · 8 Mo par fichier</small></form>`; }
async function openChat(id) { const panel = $(`#chat-${id}`); if (!panel) return; if (panel.classList.contains('hidden')) { panel.innerHTML = '<p class="legal">Chargement de la discussion…</p>'; panel.classList.remove('hidden'); try { const data = await api(`/api/orders/${id}/messages`, { headers: {} }); panel.innerHTML = chatMarkup(data.messages); panel.querySelector('.chatMessages').scrollTop = panel.querySelector('.chatMessages').scrollHeight; } catch (error) { panel.innerHTML = `<p class="legal">${escapeHtml(error.message)}</p>`; } } else panel.classList.add('hidden'); }
document.addEventListener('submit', async event => { const form = event.target.closest('[data-chat-form]'); if (!form) return; event.preventDefault(); const panel = form.closest('.chat'), id = panel.id.replace('chat-',''), message = form.elements.message.value.trim(), selected=[...form.elements.files.files]; if (!message && !selected.length) return; if(selected.length>4)return alert('Tu peux joindre 4 fichiers maximum.'); if(selected.some(file=>file.size>8*1024*1024))return alert('Chaque fichier doit faire moins de 8 Mo.'); try { const files=await Promise.all(selected.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,data:reader.result});reader.onerror=reject;reader.readAsDataURL(file);}))); await api(`/api/orders/${id}/messages`, { method: 'POST', body: JSON.stringify({ message, files }) }); const data = await api(`/api/orders/${id}/messages`, { headers: {} }); panel.innerHTML = chatMarkup(data.messages); panel.querySelector('.chatMessages').scrollTop = panel.querySelector('.chatMessages').scrollHeight; } catch (error) { alert(error.message); } });
async function updateOrder(button) { const id = button.dataset.update, status = document.querySelector(`[data-status="${id}"]`).value; try { await api('/api/admin/orders', { method: 'PATCH', body: JSON.stringify({ id, status }) }); await showAdmin(); } catch (error) { alert(error.message); } }
async function closeOrderAdmin(button) { if (!confirm('Fermer cette commande ? Elle sera retirée de ta liste principale, sans être supprimée.')) return; try { await api('/api/admin/orders', { method: 'POST', body: JSON.stringify({ id: button.dataset.closeOrder }) }); await showAdmin(); } catch (error) { alert(error.message); } }
async function addReview(button) { const rating = prompt('Ta note de 1 à 5 :'), comment = prompt('Ton avis :'); if (!rating || !comment) return; try { await api(`/api/orders/${button.dataset.review}/review`, { method: 'POST', body: JSON.stringify({ rating, comment }) }); await showOrders(); } catch (error) { alert(error.message); } }
loadHomeReviews();
refreshUser().then(() => { const page = pageFromUrl(); if (page === 'suivi') return showOrders(); if (page === 'avis') return showReviews(); if (page === 'administration') return showAdmin(); showPage(page, false); }).catch(() => { const page = pageFromUrl(); return page === 'avis' ? showReviews() : showPage(page, false); });
